package main

import (
	"context"
	"crypto/sha256"
	"encoding/base64"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"strings"
)

// download streams url into name through a temp file and a hash, and
// renames only a complete, verified file into place.
func download(ctx context.Context, c *http.Client, url, name string) (int64, error) {
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
	if err != nil {
		return 0, err
	}
	resp, err := c.Do(req)
	if err != nil {
		return 0, err
	}
	defer resp.Body.Close()

	tmp, err := os.CreateTemp(".", name+".*.part")
	if err != nil {
		return 0, err
	}
	defer os.Remove(tmp.Name()) // fails harmlessly after the rename
	h := sha256.New()
	n, err := io.Copy(io.MultiWriter(tmp, h), resp.Body)
	if err := errors.Join(err, tmp.Close()); err != nil {
		return n, err
	}
	got := "sha-256=:" + base64.StdEncoding.EncodeToString(h.Sum(nil)) + ":"
	if got != resp.Header.Get("Content-Digest") {
		return n, errors.New("digest mismatch")
	}
	return n, os.Rename(tmp.Name(), name)
}

func main() {
	body := strings.Repeat("İstanbul;Şanlıurfa;Diyarbakır\n", 300_000)
	sum := sha256.Sum256([]byte(body))
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Digest", "sha-256=:"+base64.StdEncoding.EncodeToString(sum[:])+":")
		if r.URL.Path == "/cut.csv" {
			io.WriteString(w, body[:1<<20]) // a proxy cut the body short
			return
		}
		io.WriteString(w, body)
	}))
	defer srv.Close()

	for _, name := range []string{"cities.csv", "cut.csv"} {
		n, err := download(context.Background(), srv.Client(), srv.URL+"/"+name, name)
		fmt.Printf("%s: %d bytes, err=%v\n", name, n, err)
	}
	files, _ := filepath.Glob("*.csv*")
	fmt.Println("files left:", files)
}

files.examples/04_stall_watchdog.go:
package main

import (
	"context"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
	"time"
)

const idle = time.Second

var errStalled = errors.New("stalled: no data for 1s")

// progress pushes the stall deadline back whenever bytes arrive.
type progress struct {
	r     io.Reader
	timer *time.Timer
}

func (p progress) Read(b []byte) (int, error) {
	n, err := p.r.Read(b)
	if n > 0 {
		p.timer.Reset(idle)
	}
	return n, err
}

func main() {
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		for range 5 { // slow but healthy: 2 s in total, never 1 s without data
			io.WriteString(w, strings.Repeat("x", 1000))
			http.NewResponseController(w).Flush()
			time.Sleep(400 * time.Millisecond)
		}
		<-r.Context().Done() // then the upstream hangs mid-body
	}))
	defer srv.Close()

	t := http.DefaultTransport.(*http.Transport).Clone()
	t.ResponseHeaderTimeout = 5 * time.Second
	client := &http.Client{Transport: t} // no Client.Timeout: it would cap the body too

	ctx, cancel := context.WithCancelCause(context.Background())
	defer cancel(nil)
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, srv.URL, nil)
	if err != nil {
		panic(err)
	}
	resp, err := client.Do(req)
	if err != nil {
		panic(err)
	}
	defer resp.Body.Close()
	stall := time.AfterFunc(idle, func() { cancel(errStalled) })
	defer stall.Stop()

	n, err := io.Copy(io.Discard, progress{resp.Body, stall})
	fmt.Printf("read %d bytes, err=%v\n", n, err)
	fmt.Println("errors.Is(err, errStalled):", errors.Is(err, errStalled))
}
